<div class="card-panel"><div class="notification-list"><?php foreach($notifications as $n): ?><div class="notification-item <?= $n['read_at']?'':'unread' ?>"><div><strong><?= e($n['title']) ?></strong><p><?= e($n['message']) ?></p><small><?= e($n['created_at']) ?></small></div><?php if(!$n['read_at']): ?><button class="btn btn-sm btn-light ajax-action" data-url="<?= url('/notifications/'.$n['id'].'/read') ?>">Mark read</button><?php endif; ?></div><?php endforeach; ?><?php if(!$notifications): ?><div class="empty-state">No notifications.</div><?php endif; ?></div></div>
